import { test } from 'node:test';
import assert from 'node:assert/strict';
import { HookBus } from './src/bus.ts';
import { registerAuditPlugin } from './src/plugin.ts';

test('sequential completion and subscription snapshot', async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  let offSecond: () => void = () => {};
  const offFirst = bus.on('event', async () => {
    offFirst();
    offSecond();
    bus.on('event', () => { seen.push('late'); });
    await new Promise(resolve => setTimeout(resolve, 5));
    seen.push('first');
  });
  offSecond = bus.on('event', () => { seen.push('second'); });
  await bus.emit('event', null);
  assert.deepEqual(seen, ['first', 'second']);
  await bus.emit('event', null);
  assert.deepEqual(seen, ['first', 'second', 'late']);
});

for (const asynchronous of [false, true]) {
  test(`propagates identical error and stops, async=${asynchronous}`, async () => {
    const bus = new HookBus();
    const failure = new Error('hook failure');
    let continued = false;
    bus.on('event', asynchronous ? async () => { throw failure; } : () => { throw failure; });
    bus.on('event', () => { continued = true; });
    await assert.rejects(bus.emit('event', null), error => error === failure);
    assert.equal(continued, false);
  });
}

test('audit plugin redacts before logging across emits', async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  await bus.emit('tool.after', { tool: 'read', output: 'password=secret' });
  await bus.emit('tool.after', { tool: 'write', output: 'password=other' });
  assert.deepEqual(audit, ['notice: tool output is audited', 'read: password=[redacted]', 'write: password=[redacted]']);
});



